function relevantStatOptions(options, simUI) {
  return options.filter((option) => option.stats.length == 0 || option.stats.some((stat) => simUI.individualConfig.epStats.includes(stat)) || simUI.individualConfig.includeBuffDebuffInputs.includes(option.config)).filter((option) => !simUI.individualConfig.excludeBuffDebuffInputs.includes(option.config));
}
