function makeConsumeInputFactory(args) {
  return (options, tooltip) => {
    return {
      type: "iconEnum",
      tooltip,
      numColumns: options.length > 5 ? 2 : 1,
      values: [
        { value: 0 }
      ].concat(options.map((option) => {
        const rtn = {
          actionId: option.config.actionId,
          showWhen: (player) => (!option.config.showWhen || option.config.showWhen(player)) && (option.config.faction || player.getFaction()) == player.getFaction()
        };
        if (option.config.value)
          rtn.value = option.config.value;
        return rtn;
      })),
      equals: (a, b) => a == b,
      zeroValue: 0,
      changedEvent: (player) => TypedEvent.onAny([player.consumesChangeEmitter, player.gearChangeEmitter]),
      showWhen: (player) => !args.showWhen || args.showWhen(player),
      getValue: (player) => player.getConsumes()[args.consumesFieldName],
      setValue: (eventID, player, newValue) => {
        const newConsumes = player.getConsumes();
        if (newConsumes[args.consumesFieldName] === newValue) {
          return;
        }
        newConsumes[args.consumesFieldName] = newValue;
        TypedEvent.freezeAllAndDo(() => {
          player.setConsumes(eventID, newConsumes);
          if (args.onSet) {
            args.onSet(eventID, player, newValue);
          }
        });
      }
    };
  };
}
