function scaledEpValue(stat, epRatios, result) {
  if (!result)
    return 0;
  return epRatios[0] * stat.getProtoValue(result.dps?.epValues) + epRatios[1] * stat.getProtoValue(result.hps?.epValues) + epRatios[2] * stat.getProtoValue(result.tps?.epValues) + epRatios[3] * stat.getProtoValue(result.dtps?.epValues) + epRatios[4] * stat.getProtoValue(result.tmi?.epValues) + epRatios[5] * stat.getProtoValue(result.pDeath?.epValues);
}
